mapper.sql:
WHERE sc.delete_yn = 'N'
  AND m.delete_yn  = 'N'

  AND sc.schedule_master_id = #{search.scheduleMasterId}


  AND sc.schedule_category = #{search.scheduleCategory}


  AND sc.use_yn = #{search.useYn}


  AND YEAR(sc.start_at) = #{search.year}


  AND sc.end_at >= #{search.dateFrom}


  AND sc.start_at <= #{search.dateTo}


  AND sc.schedule_title LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:
SELECT 

 WHERE sc.delete_yn  = 'N'
   AND m.delete_yn   = 'N'
   AND sc.use_yn     = 'Y'
   AND m.use_yn      = 'Y'
   AND sc.start_at  <= #{rangeEnd}
   AND sc.end_at    >= #{rangeStart}

   AND sc.schedule_master_id = #{scheduleMasterId}

 ORDER BY sc.start_at ASC, sc.schedule_title ASC

mapper.delete:
DELETE FROM tb_schedule
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_schedule
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
